 boolean needsUpdate(JSONObject app){try{PackageInfo p=Packages.installed(this,app.getString("packageName"));return p!=null&&(PersonalApps.pending(app)||Packages.version(p)<app.getJSONObject("release").getLong("versionCode"));}catch(Exception e){return false;}}
